function getColor(value: number, max: number): string {
  if (max === 0) return '#f3f4f6';
  if (value === 0) return '#f3f4f6';
  const t = value / max;
  const r = Math.round(194 + (30 - 194) * t);
  const g = Math.round(213 + (58 - 213) * t);
  const b = Math.round(236 + (95 - 236) * t);
  return `rgb(${r},${g},${b})`;
}

export default function AustriaMap({ data }: Props) {
  const [tooltip, setTooltip] = useState<{
    x: number;
    y: number;
    code: string;
    name: string;
    participants: number;
    reports: number;
  } | null>(null);

  const dataMap = new Map(data.map((d) => [d.code, d]));
  const maxParticipants = Math.max(...data.map((d) => d.participants), 1);

  const showTooltip = (e: React.MouseEvent, code: string, labelX: number, labelY: number, participants: number, reports: number) => {
    const svg = e.currentTarget.closest('svg');
    if (!svg) return;
    const rect = svg.getBoundingClientRect();
    const pt = svg.createSVGPoint();
    pt.x = labelX;
    pt.y = labelY;
    const ctm = svg.getScreenCTM();
    if (!ctm) return;
    const screenPt = pt.matrixTransform(ctm);
    setTooltip({
      x: screenPt.x - rect.left,
      y: screenPt.y - rect.top - 10,
      code: BL_SHORT[code] || code,
      name: BL_NAMES[code] || code,
      participants,
      reports,
    });
  };

  return (
    <div className="relative">
      <svg
        viewBox="-300 -120 1100 560"
        className="w-full h-auto"
        role="img"
        aria-label="Karte von Österreich und Nachbarländer mit Teilnehmern"
      >
        {/* Clip to visible area */}
        <defs>
          <clipPath id="map-clip">
            <rect x="-300" y="-120" width="1100" height="560" />
          </clipPath>
        </defs>

        {/* Background: neighbor country borders */}
        <g clipPath="url(#map-clip)">
          {Object.entries(NEIGHBOR_PATHS).map(([code, { d, labelX, labelY }]) => {
            const bl = dataMap.get(code);
            const participants = bl?.participants ?? 0;
            const reports = bl?.reports ?? 0;
            const hasPeople = participants > 0;
            const fill = hasPeople ? getColor(participants, maxParticipants) : '#e5e7eb';

            return (
              <g
                key={code}
                onMouseEnter={(e) => showTooltip(e, code, labelX, labelY, participants, reports)}
                onMouseLeave={() => setTooltip(null)}
                className={hasPeople ? 'cursor-pointer' : ''}
              >
                <path
                  d={d}
                  fill={fill}
                  stroke="#d1d5db"
                  strokeWidth="1"
                  opacity={hasPeople ? 0.9 : 0.6}
                  className="transition-opacity hover:opacity-80"
                />
                {hasPeople && (
                  <>
                    <text
                      x={labelX}
                      y={labelY - 5}
                      textAnchor="middle"
                      fontSize="12"
                      fontWeight="bold"
                      fill="#1e3a5f"
                      pointerEvents="none"
                    >
                      {BL_SHORT[code]}
                    </text>
                    <text
                      x={labelX}
                      y={labelY + 9}
                      textAnchor="middle"
                      fontSize="10"
                      fill="#1e3a5f"
                      pointerEvents="none"
                    >
                      {participants}
                    </text>
                  </>
                )}
                {!hasPeople && (
                  <text
                    x={labelX}
                    y={labelY}
                    textAnchor="middle"
                    fontSize="11"
                    fill="#9ca3af"
                    pointerEvents="none"
                  >
                    {BL_SHORT[code]}
                  </text>
                )}
              </g>
            );
          })}
        </g>

        {/* Austrian Bundesländer (foreground, on top of neighbors) */}
        {Object.entries(BL_PATHS).map(([code, { d, labelX, labelY }]) => {
          const bl = dataMap.get(code);
          const participants = bl?.participants ?? 0;
          const reports = bl?.reports ?? 0;
          const fill = getColor(participants, maxParticipants);
          const textColor = participants / maxParticipants > 0.5 ? '#ffffff' : '#1e3a5f';

          return (
            <g
              key={code}
              onMouseEnter={(e) => showTooltip(e, code, labelX, labelY, participants, reports)}
              onMouseLeave={() => setTooltip(null)}
              className="cursor-pointer"
            >
              <path
                d={d}
                fill={fill}
                stroke="#ffffff"
                strokeWidth="2"
                className="transition-opacity hover:opacity-80"
              />
              <text
                x={labelX}
                y={labelY - 5}
                textAnchor="middle"
                fontSize="10"
                fontWeight="bold"
                fill={textColor}
                pointerEvents="none"
              >
                {BL_SHORT[code]}
              </text>
              <text
                x={labelX}
                y={labelY + 7}
                textAnchor="middle"
                fontSize="9"
                fill={textColor}
                pointerEvents="none"
              >
                {participants}
              </text>
            </g>
          );
        })}
      </svg>

      {/* Tooltip */}
      {tooltip && (
        <div
          className="absolute bg-gray-900 text-white text-xs rounded px-2 py-1.5 pointer-events-none shadow-lg z-10 whitespace-nowrap"
          style={{
            left: tooltip.x,
            top: tooltip.y,
            transform: 'translate(-50%, -100%)',
          }}
        >
          <div className="font-bold">{tooltip.code} — {tooltip.name}</div>
          <div>Teilnehmer: {tooltip.participants}</div>
          <div>Rapporte: {tooltip.reports}</div>
        </div>
      )}

      {/* Legend */}
      <div className="flex items-center justify-center gap-2 mt-2 text-xs text-gray-500">
        <span>0</span>
        <div
          className="h-3 w-32 rounded"
          style={{
            background: 'linear-gradient(to right, #c2d5ec, #1e3a5f)',
          }}
        />
        <span>{maxParticipants}</span>
        <span className="ml-1 text-gray-400">Teilnehmer</span>
      </div>
    </div>
  );
}
